# 1. Read existing master_database.csv
with open('master_database.csv', 'r', encoding='utf-8') as f:
    master_header = [c.strip() for c in f.readline().strip().split(',')]

df_master = pd.read_csv('master_database.csv')

# 2. Filter out all existing K27 / K277 rows
df_non_k27 = df_master[~df_master['Server'].isin(['K27', 'K277'])].copy()
print(f"Kept {len(df_non_k27)} non-K27 rows from master_database.csv")

# 3. Parse new K27 data
reader = csv.DictReader(io.StringIO(raw_csv))
new_k27_rows = []
for row in reader:
    p_name = row['Player Name'].strip()
    # Server is K27
    row_dict = {k: v.strip() for k, v in row.items()}
    row_dict['Server'] = 'K27'
    row_dict['Player Name'] = p_name
    new_k27_rows.append(row_dict)

print(f"Parsed {len(new_k27_rows)} new K27 rows")

df_new_k27 = pd.DataFrame(new_k27_rows)

# Reorder columns to match master_header
df_new_k27 = df_new_k27[master_header]

# 4. Concatenate and save master_database.csv
df_final_master = pd.concat([df_non_k27, df_new_k27], ignore_index=True)
df_final_master.to_csv('master_database.csv', index=False, encoding='utf-8')
print(f"Updated master_database.csv with total {len(df_final_master)} rows")

# 5. Run build_json.py to regenerate public_players.json, players.json, and kingdoms.json
print("Running build_json.py...")
res = subprocess.run(['python3', 'build_json.py'], capture_output=True, text=True)
print(res.stdout)
if res.stderr:
    print("Error in build_json.py:", res.stderr)
